        dirs[:]=[]
        continue
    for fn in files:
        if not fn.endswith('.xlsx'):
            continue
        p=os.path.join(root,fn)
        try:
            z=zipfile.ZipFile(p)
            blob=b''
            for n in z.namelist():
                if 'sharedStrings' in n or 'sheet' in n or 'workbook' in n:
                    try: blob+=z.read(n)
